{"translations":{"cue-1":"Bạn có dám tin không?","cue-2":"Âm thanh nút điều hướng đầy mê hoặc của Volvo,","cue-3":"thực chất hoàn toàn không phải do lập trình viên tạo ra.","cue-4":"Các hãng xe khác khi làm âm thanh nút bấm,","cue-5":"đều ngồi trong văn phòng chỉnh thông số máy tính.","cue-6":"Nhưng các nhà thiết kế của Volvo lại không làm như vậy.","cue-7":"Ông ấy nói,","cue-8":"âm thanh nút bấm này","cue-9":"chủ xe sẽ phải nghe hàng chục ngàn lần.","cue-10":"Không được chói tai, không được gượng gạo,","cue-11":"và càng không được gây bực bội khi nghe lâu.","cue-12":"Ngay cả khi bị kẹt xe giữa dòng đường đông đúc,","cue-13":"nghe thấy nó cũng có thể khiến lòng người tĩnh lặng.","cue-14":"Thế là ông dẫn theo toàn bộ đội ngũ,","cue-15":"lao vào rừng sâu và ở lại trọn vẹn hai ngày.","cue-16":"Bẻ gãy hơn ba trăm cành cây khác nhau,","cue-17":"để thử nghiệm từng loại gỗ,","cue-18":"cũng như âm thanh bẻ gãy của từng độ dày mỏng.","cue-19":"Hết lần này đến lần khác,","cue-20":"thu lại hơn ba trăm loại âm thanh của thiên nhiên.","cue-21":"Mục tiêu chỉ có một:","cue-22":"Tìm ra một","cue-23":"âm thanh dịu dàng, tự nhiên, nghe một ngàn hay mười ngàn lần","cue-24":"cũng sẽ không thấy khó chịu.","cue-25":"Cuối cùng, sau vô số lần thử nghiệm,","cue-26":"họ đã tìm ra.","cue-27":"Giống như khi một cành cây nhỏ nhẹ nhàng bị uốn cong,","cue-28":"tiếng \"rắc\" êm ái đó.","cue-29":"Sau này, họ đã số hóa đoạn âm thanh đến từ khu rừng lớn này,","cue-30":"tinh chỉnh nhiều lần,","cue-31":"làm mượt,","cue-32":"mới trở thành tiếng click độc đáo của nút điều hướng Volvo ngày nay.","cue-33":"Đó cũng là lý do tại sao","cue-34":"nhiều chủ xe đều nói nút bấm của Volvo","cue-35":"là nút bấm mang tính chữa lành nhất trên mạng.","cue-36":"Nghe thấy âm thanh đến từ thiên nhiên này,","cue-37":"dù bên ngoài có kẹt xe đến mấy,","cue-38":"tâm trạng có bực bội đến đâu,","cue-39":"cũng có thể ngay lập tức được xoa dịu.","cue-40":"Hóa ra sự cao cấp","cue-41":"thực sự ẩn giấu trong","cue-42":"những chi tiết dễ bị bỏ qua đó.","cue-43":"Bạn còn từng thấy trên xe hơi","cue-44":"những thiết kế chi tiết nào ấm áp như vậy nữa không?"}}
[/CANDIDATE_JSON]
